property_tests.invariant_check:
pre_reset_statuses = {node.id: node.status for node in plan.nodes}
result = CliRunner().invoke(af_plan_cmd, ['--reset', '--yes'])
assert result.exit_code == 0
post_reset_rows = conn.execute('SELECT node_id, status FROM plan_nodes').fetchall()
for node_id, post_status in post_reset_rows:
    pre_status = pre_reset_statuses[node_id]
    if pre_status not in {'failed', 'blocked', 'in_progress'}:
        assert post_status == pre_status, f'Node {node_id} with pre-status {pre_status} was unexpectedly changed to {post_status}'

edge_case_tests.assertion_pseudocode:
from agentfox.graph.planner import run_plan
try:
    run_plan(clear=True, reset=True)
    assert False, 'Expected ValueError'
except ValueError as e:
    assert 'clear' in str(e).lower() or 'reset' in str(e).lower()
except SystemExit:
    assert False, 'run_plan must not call sys.exit'

from agentfox.graph.planner import run_plan
with patch('agentfox.graph.persistence.load_plan', return_value=None):
    try:
        run_plan(clear=True)
        assert False, 'Expected RuntimeError'
    except RuntimeError as e:
        assert 'no plan' in str(e).lower() or 'plan' in str(e).lower()
    except SystemExit:
        assert False, 'run_plan must not call sys.exit'
